'use client'

// The document layout primitives (PRD §6) for the HTML preview. They draw the
// layout engine's output (src/lib/documents/layout): lines are already broken
// with the theme's real font metrics and every box has its engine height, so
// the browser never re-wraps or reflows anything. Typography comes only from
// the --doc-* CSS variables generated by tokens.ts; this file names no font
// family and no font size.

import React, { type CSSProperties } from 'react'

import { leading, type Cell, type FragmentBody, type LogoLayout, type TableRowLayout, type ValueLayout } from '@/lib/documents/layout/blocks'
import type { PageLayout, PlacedFragment } from '@/lib/documents/layout/paginate'
import type { Line, Segment } from '@/lib/documents/layout/text'
import { BRAND, CHART, cssTypePrefix, FLOW, PRINT_TYPE, SPACE, TABLE, printTypeKey, type PrintTypeKey, type TextStyle } from '@/lib/documents/tokens'

import styles from './documentPreview.module.css'

const PT_TO_PX = 96 / 72
const pt = (n: number) => `${n}pt`

function kebab(key: string): string {
  return key.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)
}

/** Inline style for a token text style. Every property is a CSS variable from tokens.ts. */
export function type(key: PrintTypeKey): CSSProperties {
  const p = `--doc-type-${kebab(key)}`
  return {
    fontFamily: `var(${p}-family)`,
    fontWeight: `var(${p}-weight)` as CSSProperties['fontWeight'],
    fontStyle: `var(${p}-style)`,
    fontSize: `var(${p}-size)`,
    lineHeight: `var(${p}-leading)`,
    letterSpacing: `var(${p}-tracking)`,
    textTransform: `var(${p}-case)` as CSSProperties['textTransform'],
    // Real italics/bolds only: never let the browser fake a missing cut.
    fontSynthesis: 'none',
  }
}

/** Inline style for any token style object (print or slide scale). */
export function typeOfStyle(style: TextStyle): CSSProperties {
  const p = cssTypePrefix(style)
  if (!p) throw new Error('Text style is not a token')
  return {
    fontFamily: `var(${p}-family)`,
    fontWeight: `var(${p}-weight)` as CSSProperties['fontWeight'],
    fontStyle: `var(${p}-style)`,
    fontSize: `var(${p}-size)`,
    lineHeight: `var(${p}-leading)`,
    letterSpacing: `var(${p}-tracking)`,
    textTransform: `var(${p}-case)` as CSSProperties['textTransform'],
    fontSynthesis: 'none',
  }
}

// ── End of token style helpers ──

/** An engine line in any token style (used by slides). */
export function StyledLineView({ line, style }: { line: Line; style: TextStyle }) {
  const lh = style.sizePt * style.lineHeight
  return (
    <span className={styles.line} style={{ height: pt(lh), lineHeight: pt(lh) }} data-line data-width={line.width.toFixed(3)}>
      {line.segments.map((s, i) => <span key={i} className={s.style !== style && s.style.role === 'function' ? styles.citation : undefined} style={{ ...typeOfStyle(s.style), lineHeight: pt(lh) }}>{s.text}</span>)}
    </span>
  )
}

/** Bar plot shared by the print chart and the chart slide. Geometry in pt; text in the given label style. */
export function BarPlot({ node, widthPt, heightPt, labelStyle }: { node: Extract<FragmentBody, { primitive: 'chart' }>['node']; widthPt: number; heightPt: number; labelStyle: CSSProperties }) {
  const points = node.series[0]?.points ?? []
  const labels = node.valueLabels[0] ?? []
  const max = Math.max(1, ...points.map((p) => p.y))
  // The viewBox is in CSS px at 100% zoom, so one user unit is one px and token text (pt) renders true size.
  const px = (n: number) => n * PT_TO_PX
  const w = px(widthPt), h = px(heightPt)
  const top = px(CHART.valueLabelBandPt), bottom = px(CHART.axisLabelBandPt)
  const band = w / Math.max(1, points.length)
  return (
    <svg className={styles.chart} style={{ width: pt(widthPt), height: pt(heightPt) }} viewBox={`0 0 ${w} ${h}`} role="img" aria-label={`${node.title}. ${node.yLabel} by ${node.xLabel}.`} aria-describedby={`${node.id}-summary`}>
      <line x1={0} x2={w} y1={h - bottom} y2={h - bottom} className={styles.chartAxis} strokeWidth={px(CHART.axisStrokePt)} />
      {points.map((p, i) => {
        const barH = ((h - bottom - top) * p.y) / max
        const barW = band * CHART.barShare
        const x = i * band + (band - barW) / 2
        return (
          <g key={p.x}>
            <rect x={x} y={h - bottom - barH} width={barW} height={barH} className={styles.chartBar} />
            <text x={x + barW / 2} y={h - bottom - barH - px(CHART.valueLabelGapPt)} textAnchor="middle" className={styles.chartText} style={labelStyle}>{labels[i]}</text>
            <text x={x + barW / 2} y={h - bottom + px(CHART.axisLabelBandPt) - px(CHART.valueLabelGapPt)} textAnchor="middle" className={styles.chartText} style={labelStyle}>{p.x}</text>
          </g>
        )
      })}
    </svg>
  )
}

// ── Lines and inline primitives ──────────────────────────────────────────────

/** Citation (inline primitive): a marker segment, glued to its claim by the engine. */
export function Citation({ segment }: { segment: Segment }) {
  return (
    <span className={styles.citation} style={type('citation')}>
      <span className={styles.srOnly}>Sources </span>{segment.text}
    </span>
  )
}

/** One engine line: fixed height, no wrapping. `data-width` is the engine's width, for the parity check. */
export function LineView({ line, lineStyle }: { line: Line; lineStyle: PrintTypeKey }) {
  const lh = leading(PRINT_TYPE[lineStyle])
  return (
    <span className={styles.line} style={{ height: pt(lh), lineHeight: pt(lh) }} data-line data-width={line.width.toFixed(3)}>
      {line.segments.map((s, i) => {
        const key = printTypeKey(s.style) ?? lineStyle
        if (key === 'citation' && lineStyle !== 'citation') return <Citation key={i} segment={s} />
        const content = key === 'emphasis' ? <em>{s.text}</em> : s.text
        return <span key={i} style={{ ...type(key), lineHeight: pt(lh) }}>{content}</span>
      })}
    </span>
  )
}

function Lines({ lines, lineStyle }: { lines: readonly Line[]; lineStyle: PrintTypeKey }) {
  return <>{lines.map((l, i) => <LineView key={i} line={l} lineStyle={lineStyle} />)}</>
}

/** MissingField (inline primitive): a required fact that was not supplied, shown where it belongs. */
export function MissingField({ value, fieldId }: { value: Extract<ValueLayout, { kind: 'missing' }>; fieldId?: string }) {
  return (
    <span className={styles.missing} style={{ width: pt(value.boxWidth - 2 * FLOW.missing.border - 2 * FLOW.missing.paddingX), height: pt(value.height - 2 * FLOW.missing.border), borderWidth: pt(FLOW.missing.border), paddingInline: pt(FLOW.missing.paddingX) }} data-field-id={fieldId}>
      <Lines lines={value.lines} lineStyle="label" />
    </span>
  )
}

export function Value({ value, align = 'start', fieldId }: { value: ValueLayout | null; align?: 'start' | 'end'; fieldId?: string }) {
  if (!value) return null
  if (value.kind === 'missing') return <MissingField value={value} fieldId={fieldId} />
  if (value.kind === 'unknown') {
    return (
      <span className={styles.unknown} data-align={align}>
        <Lines lines={value.lines} lineStyle={value.style} />
        {value.reasonLines.length > 0 && <span className={styles.unknownReasons} style={{ marginTop: pt(SPACE.xxs) }}><Lines lines={value.reasonLines} lineStyle="label" /></span>}
      </span>
    )
  }
  return <span className={styles.value} data-align={align}><Lines lines={value.lines} lineStyle={value.style} /></span>
}

/** KeyValueField: label above value (or MissingField), placed by the engine. */
export function KeyValueField({ cell, labelGap }: { cell: Cell; labelGap: number }) {
  return (
    <div className={styles.cell} style={{ left: pt(cell.x), top: pt(cell.y), width: pt(cell.width), height: pt(cell.height) }} data-status={cell.value.kind}>
      <dt className={styles.muted}><Lines lines={cell.label} lineStyle="label" /></dt>
      <dd style={{ marginTop: pt(labelGap) }}><Value value={cell.value} /></dd>
    </div>
  )
}

// ── Block primitives ─────────────────────────────────────────────────────────

function Logo({ logo }: { logo: LogoLayout }) {
  if (logo.kind === 'image') {
    // eslint-disable-next-line @next/next/no-img-element -- local fixture asset, checked for availability before layout
    return <img className={styles.logo} src={logo.asset.src} alt={logo.asset.alt} style={{ width: pt(logo.width), height: pt(logo.height) }} />
  }
  const note = logo.lines.map((l) => l.segments.map((s) => s.text).join('')).join(' ')
  return (
    <span className={styles.logoFallback} role="img" aria-label={`${note}; neutral placeholder shown`} style={{ width: pt(logo.width), height: pt(logo.height) }}>
      <span aria-hidden="true"><Lines lines={logo.lines} lineStyle="label" /></span>
    </span>
  )
}

export function Letterhead({ body }: { body: Extract<FragmentBody, { primitive: 'letterhead' }> }) {
  return (
    <header className={styles.letterhead} style={{ paddingBottom: pt(FLOW.letterhead.paddingBottom), borderBottomWidth: pt(BRAND.accentRulePt) }}>
      <div className={styles.letterheadRow} style={{ height: pt(body.rowHeight), gap: pt(FLOW.letterhead.gap) }}>
        <Logo logo={body.logo} />
        <p className={styles.issuerName} style={{ marginTop: pt(body.issuerY) }}><Lines lines={body.issuerLines} lineStyle="issuerName" /></p>
      </div>
    </header>
  )
}

export function TitleBlock({ body }: { body: Extract<FragmentBody, { primitive: 'title-block' }> }) {
  const F = FLOW.titleBlock
  return (
    <div className={styles.fill}>
      {body.draft && (
        <p className={styles.draftMarker} style={{ top: pt(F.paddingTop), width: pt(body.draft.width - 2 * (FLOW.missing.border + F.draftPaddingX)), height: pt(body.draft.height - 2 * (FLOW.missing.border + F.draftPaddingY)), borderWidth: pt(FLOW.missing.border), padding: `${pt(F.draftPaddingY)} ${pt(F.draftPaddingX)}` }}>
          <Lines lines={body.draft.lines} lineStyle="draftMarker" />
        </p>
      )}
      <h1 className={styles.abs} style={{ top: pt(body.titleY) }}><Value value={body.title} /></h1>
      {body.meta.length > 0 && (
        <dl className={styles.abs} style={{ top: pt(body.metaY) }}>
          {body.meta.map((c, i) => <KeyValueField key={i} cell={c} labelGap={F.labelGap} />)}
        </dl>
      )}
    </div>
  )
}

export function KeyValueGroup({ body, label }: { body: Extract<FragmentBody, { primitive: 'key-value-group' }>; label?: string }) {
  return (
    <section className={styles.fill} aria-label={label}>
      {body.title && <h2 className={styles.muted}><Lines lines={body.title} lineStyle="label" /></h2>}
      <dl className={styles.abs} style={{ top: pt(body.cellsY) }}>
        {body.cells.map((c, i) => <KeyValueField key={i} cell={c} labelGap={FLOW.keyValueGroup.labelGap} />)}
      </dl>
    </section>
  )
}

export function SectionHeading({ body }: { body: Extract<FragmentBody, { primitive: 'text' }> }) {
  const Tag = body.level === 3 ? 'h3' : 'h2'
  return <Tag><Lines lines={body.lines} lineStyle="sectionHeading" /></Tag>
}

export function Summary({ body }: { body: Extract<FragmentBody, { primitive: 'text' }> }) {
  return (
    <p className={styles.summary} style={{ padding: `${pt(FLOW.summary.paddingY)} 0 ${pt(FLOW.summary.paddingY)} ${pt(FLOW.summary.inset)}`, borderLeftWidth: pt(BRAND.accentRulePt) }}>
      <Lines lines={body.lines} lineStyle="body" />
    </p>
  )
}

export function Paragraph({ body }: { body: Extract<FragmentBody, { primitive: 'text' }> }) {
  if (body.role === 'pull-quote') return <blockquote style={{ paddingLeft: pt(FLOW.pullQuote.indent) }}><Lines lines={body.lines} lineStyle="pullQuote" /></blockquote>
  return <p><Lines lines={body.lines} lineStyle="body" /></p>
}

export function Callout({ body }: { body: Extract<FragmentBody, { primitive: 'text' }> }) {
  return (
    <aside className={styles.callout} data-tone={body.tone} data-audience={body.audience} style={{ padding: `${pt(FLOW.callout.paddingY)} ${pt(FLOW.callout.paddingX)}`, borderLeftWidth: pt(BRAND.accentRulePt) }}>
      {body.label && <p className={styles.muted} style={{ marginBottom: pt(FLOW.callout.labelGap) }}><Lines lines={body.label} lineStyle="label" /></p>}
      <p><Lines lines={body.lines} lineStyle="body" /></p>
    </aside>
  )
}

export function List({ body }: { body: Extract<FragmentBody, { primitive: 'list' }> }) {
  const Tag = body.ordered ? 'ol' : 'ul'
  return (
    <Tag className={styles.list} start={body.ordered ? body.items[0]?.number : undefined}>
      {body.items.map((item) => (
        <li key={item.number} value={body.ordered ? item.number : undefined} style={{ marginTop: pt(item.gapBefore), paddingLeft: pt(FLOW.list.indent) }}>
          {item.startsItem && <span className={styles.marker} aria-hidden="true" style={{ ...type('body'), width: pt(FLOW.list.indent) }}>{item.marker}</span>}
          <Lines lines={item.lines} lineStyle="body" />
        </li>
      ))}
    </Tag>
  )
}

function Row({ row, columns }: { row: TableRowLayout; columns: Extract<FragmentBody, { primitive: 'table' }>['columns'] }) {
  return (
    <tr style={{ height: pt(row.height) }} data-row-id={row.id}>
      {row.cells.map((cell, i) => (
        <td key={i} data-align={columns[i].align} style={{ padding: `${pt(TABLE.cellPaddingYPt)} ${pt(TABLE.cellPaddingXPt)}`, borderBottomWidth: pt(TABLE.ruleWidthPt) }}>
          {i === 0 && row.continuedLabel && (
            <span className={`${styles.muted} ${styles.value}`} style={{ marginBottom: pt(SPACE.xxs) }}>
              <LineView line={row.continuedLabel} lineStyle="label" />
            </span>
          )}
          <Value value={cell} align={columns[i].align} />
        </td>
      ))}
    </tr>
  )
}

/** Table and InvoiceLineItems: fixed column widths from the engine; header repeated on continuations. */
export function Table({ body, label }: { body: Extract<FragmentBody, { primitive: 'table' }>; label: string }) {
  return (
    <figure className={styles.fill}>
      {body.caption && <figcaption className={styles.muted} style={{ marginBottom: pt(FLOW.table.captionGap) }}><Lines lines={body.caption} lineStyle="label" /></figcaption>}
      <table className={styles.table} aria-label={body.repeatedHeader ? `${label} (continued)` : label}>
        <colgroup>{body.columns.map((c, i) => <col key={i} style={{ width: pt(c.width) }} />)}</colgroup>
        <thead>
          <tr style={{ height: pt(body.header.height) }}>
            {body.header.cells.map((lines, i) => (
              <th key={i} scope="col" data-align={body.columns[i].align} style={{ padding: `${pt(TABLE.cellPaddingYPt)} ${pt(TABLE.cellPaddingXPt)}`, borderBottomWidth: pt(TABLE.headerRuleWidthPt) }}>
                <Lines lines={lines} lineStyle="tableHeader" />
              </th>
            ))}
          </tr>
        </thead>
        <tbody>{body.rows.map((r) => <Row key={`${r.id}:${r.continuedFromPrevious}`} row={r} columns={body.columns} />)}</tbody>
      </table>
    </figure>
  )
}

export const InvoiceLineItems = Table

export function Totals({ body, complete }: { body: Extract<FragmentBody, { primitive: 'totals' }>; complete: boolean }) {
  return (
    <table className={styles.totals} style={{ marginLeft: pt(body.x), width: pt(body.width) }}>
      <caption className={styles.srOnly}>Totals{complete ? '' : ' (incomplete)'}</caption>
      <colgroup><col style={{ width: pt(body.labelWidth) }} /><col /></colgroup>
      <tbody>
        {body.rows.map((r) => {
          const top = pt(r.grand ? FLOW.totals.grandPaddingTop : TABLE.cellPaddingYPt)
          const rule = r.grand ? pt(TABLE.totalsRuleWidthPt) : 0
          return (
            <tr key={r.id} data-grand={r.grand || undefined} style={{ height: pt(r.height) }}>
              <th scope="row" style={{ padding: `${top} ${pt(TABLE.cellPaddingXPt)} ${pt(TABLE.cellPaddingYPt)}`, borderTopWidth: rule }}>
                <Lines lines={r.label} lineStyle={r.labelStyle} />
              </th>
              <td data-align="end" style={{ padding: `${top} ${pt(TABLE.cellPaddingXPt)} ${pt(TABLE.cellPaddingYPt)} ${pt(FLOW.totals.columnGap + TABLE.cellPaddingXPt)}`, borderTopWidth: rule }}>
                <Value value={r.value} align="end" />
              </td>
            </tr>
          )
        })}
      </tbody>
    </table>
  )
}

export function ChartWithDataSummary({ body, width }: { body: Extract<FragmentBody, { primitive: 'chart' }>; width: number }) {
  return (
    <figure className={styles.fill}>
      <figcaption><Lines lines={body.title} lineStyle="label" /></figcaption>
      <div style={{ marginTop: pt(FLOW.chart.titleGap) }}><BarPlot node={body.node} widthPt={width} heightPt={body.plotHeight} labelStyle={type('label')} /></div>
      <p className={styles.muted} style={{ marginTop: pt(FLOW.chart.noteGap) }}><Lines lines={body.axes} lineStyle="label" /></p>
      <p id={`${body.node.id}-summary`} style={{ marginTop: pt(FLOW.chart.noteGap) }}><Lines lines={body.summary} lineStyle="label" /></p>
    </figure>
  )
}

export function ImageWithCaption({ body }: { body: Extract<FragmentBody, { primitive: 'image' }> }) {
  return (
    <figure className={styles.fill}>
      {body.available
        // eslint-disable-next-line @next/next/no-img-element -- local fixture asset, checked for availability before layout
        ? <img src={body.asset.src} alt={body.asset.alt} style={{ display: 'block', width: pt(body.width), height: pt(body.height) }} />
        : <span className={styles.logoFallback} style={{ width: pt(body.width), height: pt(body.height) }}><span><Lines lines={body.note} lineStyle="label" /></span></span>}
      <figcaption style={{ marginTop: pt(FLOW.image.captionGap) }}><Lines lines={body.caption} lineStyle="label" /></figcaption>
    </figure>
  )
}

export function SourceList({ body }: { body: Extract<FragmentBody, { primitive: 'source-list' }> }) {
  return (
    <ol className={styles.list}>
      {body.entries.map((e) => (
        <li key={e.number} value={e.number} id={`source-${e.number}`} style={{ marginTop: pt(e.gapBefore), paddingLeft: pt(FLOW.sourceList.indent) }}>
          <span className={styles.marker} aria-hidden="true" style={{ ...type('citation'), width: pt(FLOW.sourceList.indent) }}>{e.number}.</span>
          <Lines lines={e.lines} lineStyle="citation" />
        </li>
      ))}
    </ol>
  )
}

/** PageBreakHint: in the preview, shows why this page began (workbench overlay, not document content). */
export function PageBreakHint({ reason }: { reason: string }) {
  return <p className={styles.breakHint} role="note" style={type('footer')}>Page break: {reason}</p>
}

/** PageFooter: document identification and "Page n of N" on every page. */
export function PageFooter({ page }: { page: PageLayout }) {
  return (
    <footer className={styles.footer} style={{ top: pt(page.footer.y), left: pt(page.content.x), width: pt(page.content.width) }}>
      <span className={styles.muted}><LineView line={page.footer.identification} lineStyle="footer" /></span>
      <span className={styles.muted}><LineView line={page.footer.pageLabel} lineStyle="footer" /></span>
    </footer>
  )
}

const LABELS: Partial<Record<string, string>> = { 'invoice-line-items': 'Line items', table: 'Table' }

/** Renders one placed fragment with its primitive. */
export function FragmentView({ fragment, contentWidth, complete }: { fragment: PlacedFragment; contentWidth: number; complete: boolean }) {
  const { body } = fragment
  const inner = (() => {
    switch (body.primitive) {
      case 'letterhead': return <Letterhead body={body} />
      case 'title-block': return <TitleBlock body={body} />
      case 'text':
        if (body.role === 'section-heading') return <SectionHeading body={body} />
        if (body.role === 'summary') return <Summary body={body} />
        if (body.role === 'callout') return <Callout body={body} />
        return <Paragraph body={body} />
      case 'list': return <List body={body} />
      case 'key-value-group': return <KeyValueGroup body={body} label={fragment.nodeId} />
      case 'table': return <Table body={body} label={LABELS[fragment.primitive] ?? 'Table'} />
      case 'totals': return <Totals body={body} complete={complete} />
      case 'chart': return <ChartWithDataSummary body={body} width={contentWidth} />
      case 'image': return <ImageWithCaption body={body} />
      case 'source-list': return <SourceList body={body} />
    }
  })()
  return (
    <div className={styles.fragment} style={{ top: pt(fragment.y), height: pt(fragment.height) }} data-fragment={fragment.key} data-primitive={fragment.primitive} data-height={fragment.height.toFixed(3)}>
      {inner}
    </div>
  )
}
